h", "label": "Ghi chú các yêu cầu đặc biệt về kỹ thuật, gia công", "level": "req", "active": true, "created_at": "2026-11-16T05:53:23.637918+00:00"}, {"id": "ba79fb16-914c-4871-83a4-9b9ec6659f0c", "ord": 4, "auto": null, "proc": "QT0", "step": "boc_tach", "label": "Định mức sản xuất và thời gian gia công", "level": "req", "active": true, "created_at": "2026-11-09T05:19:42.792987+00:00"}, {"id": "ec4ba0df-f19c-4e65-81ec-e7b0ebbe2f59", "ord": 2, "auto": null, "proc": "QT0", "step": "boc_tach", "label": "Thiết bị, công cụ gia công đầy đủ", "level": "req", "active": true, "created_at": "2026-11-09T05:19:42.792987+00:00"}, {"id": "d883908d-e7eb-4b6e-bb18-9fe2b1a6354e", "ord": 3, "auto": null, "proc": "QT0", "step": "kiem_tra", "label": "Định mức sản xuất và thời gian gia công đạt", "level": "req", "active": true, "created_at": "2026-11-14T07:01:54.844708+00:00"}, {"id": "4682cdee-b1ce-421b-b848-0a75fc1f7aea", "ord": 1, "auto": null, "proc": "QT0", "step": "tao_ds", "label": "Danh sác tấm, diện tích tấm, phụ kiện đã đối chiều so với danh sách đặt hàng", "level": "req", "active": true, "created_at": "2026-11-09T05:19:42.792987+00:00"}, {"id": "b4d8dc76-4b5a-46f0-bf1e-d37b8d400a96", "ord": 4, "auto": null, "proc": "QT0", "step": "kiem_tra", "label": "Các yêu cầu đặc biệt về kỹ thuật, gia công thống nhất", "level": "req", "active": true, "created_at": "2026-11-14T07:01:54.844708+00:00"}, {"id": "2311c369-6b8b-4ec5-a58d-5f7dcd31da2a", "ord": 2, "auto": null, "proc": "QT0", "step": "tao_ds", "label": "Nguyên liệu đã phối phù hợp với tồn kho, mua hàng", "level": "req", "active": true, "created_at": "2026-11-09T05:19:42.792987+00:00"}, {"id": "ace065c0-4b93-4a14-82c4-1e9c7abd2445", "ord": 1, "auto": null, "proc": "QT0", "step": "duyet", "label": "Tổng thể diện tích trải phẳng, hao hụt khớp dự toán", "level": "req", "active": true, "created_at": "2026-11-09T05:19:42.792987+00:00"}, {"id": "71ef3166-d404-4aa4-aeb4-b5aa85902bd9", "ord": 2, "auto": null, "proc": "QT0", "step": "duye