insert into public.step_guides select * from jsonb_populate_recordset(null::public.step_guides, E'[{"key": "sim.start", "ord": 0, "prev": null, "todo": "Vào Đơn hàng → Tạo đơn\\nNhập khách hàng, dự án, kênh nhận, hạn báo giá, hạn giao\\nLưu → QT0 tự mở", "links": "", "notes": "", "title": "Kinh doanh tạo đơn hàng", "purpose": "Khách gửi yêu cầu qua Email / điện thoại. Kinh doanh tạo đơn: khách hàng, dự án, hạn báo giá, hạn giao. Hệ thống mở QT0 cho Phương Nam.", "updated_at": "2026-11-10T00:22:38.682729+00:00", "updated_by": null}, {"key": "QT0.*.boc_tach", "ord": 11, "prev": null, "todo": "Nhập vật liệu, hao hụt, đường hàn / chấn, m² đột, vấn đề kỹ thuật\\nĐính kèm file Excel bóc tách chi tiết\\nBấm Xong bóc tách → tạo DS tấm", "links": "", "notes": "Bắt buộc có file Excel bóc tách, nếu không sẽ không chuyển bước được.", "title": "QT0 · Bóc tách kỹ thuật", "purpose": "Kỹ thuật bóc tách bản vẽ: vật liệu, độ dày, kích thước từng tấm.", "updated_at": "2026-11-10T00:22:38.682729+00:00", "updated_by": null}, {"key": "QT0.*.tao_ds", "ord": 12, "prev": null, "todo": "Tải Excel theo mẫu hoặc dán từ Excel vào bảng Danh sách tấm\\nKiểm tra tổng m², kg tự tính\\nGửi kiểm tra", "links": "", "notes": "Bảng trống thì không chuyển bước được.", "title": "QT0 · Tạo danh sách tấm", "purpose": "Admin nhập danh sách tấm vào phiếu (bảng, file đính kèm).", "updated_at": "2026-11-10T00:22:38.682729+00:00", "updated_by": null}, {"key": "QT0.*.kiem_tra", "ord": 13, "prev": null, "todo": "Đối chiếu danh sách với bản vẽ và ghi chú\\nThêm lưu ý kỹ thuật nếu có\\nĐạt → gửi duyệt; chưa đạt → Trả về kèm lý do", "links": "", "notes": "", "title": "QT0 · Kiểm tra", "purpose": "Người kiểm tra soát lại danh sách. Sai → trả về kèm lý do.", "updated_at": "2026-11-10T00:22:38.682729+00:00", "updated_by": null}, {"key": "sim.back", "ord": 90, "prev": null, "todo": "", "links": "", "notes": "", "title": "Tình huống trả về", "purpose": "Người kiểm tra thấy sai (ví dụ đơn giá) → bấm Trả về, ghi lý do. Phiếu quay lại bước Lập, lý do hiện trong Hành trình duyệt.", "updated_at": "2026-11-10T00:22:38.682729+00:00", "updated_by": null}, {"key": "sim.recheck", "ord": 92, "prev": null, "todo": "", "links": "", "notes": "", "title": "Kiểm tra lại", "purpose": "Lần này đạt → gửi duyệt.", "updated_at": "2026-11-10T00:22:38.682729+00:00", "updated_by": null}, {"key": "sim.extra", "ord": 93, "prev": null, "todo": "", "links": "", "notes": "", "title": "Cấp duyệt thêm", "purpose": "Cấp duyệt thêm (cấu hình ở Luồng duyệt). {cap} xem phiếu và ghi chú rồi duyệt hoặc trả về.", "updated_at": "2026-11-10T00:22:38.682729+00:00", "updated_by": null}, {"key": "sim.hand", "ord": 94, "prev": null, "todo": "", "links": "", "notes": "", "title": "Nhận phiếu (chuyển công ty)", "purpose": "{cty} đã duyệt → hệ thống tự tạo phiếu cho {cty_sau} và báo Zalo cho người lập.", "updated_at": "2026-11-10T00:22:38.682729+00:00", "updated_by": null}, {"key": "sim.done", "ord": 96, "prev": null, "todo": "", "links": "", "notes": "", "title": "Đơn hoàn tất", "purpose": "Toàn bộ QT0 → QT3 đã xong. Thời gian từng bước được ghi lại cho Thống kê và Hiệu quả.", "updated_at": "2026-11-10T00:22:38.682729+00:00", "updated_by": null}, {"key": "QT0.*.tiep_nhan", "ord": 10, "prev": {"todo": "Tải bản vẽ / tài liệu khách gửi lên phiếu\\nGhi chú yêu cầu đặc biệt của khách\\nBấm chuyển bóc tách", "links": "", "notes": "Thiếu bản vẽ thì hỏi lại khách trước khi chuyển.", "purpose": "Admin nhận bản vẽ, kiểm tra đủ hồ sơ rồi chuyển cho kỹ thuật.", "updated_at": "2026-11-10T00:22:38.682729+00:00", "updated_by": null}, "todo": "Tải bản vẽ / tài liệu khách gửi lên phiếu\\nGhi chú yêu cầu đặc biệt của khách\\nBấm chuyển sang bộ phận bóc tách kỹ thuật", "links": "", "notes": "Thiếu bản vẽ thì hỏi lại khách trước khi chuyển.", "title": "QT0 · Admin tiếp nhận", "purpose": "Admin nhận bản vẽ, kiểm tra đủ hồ sơ rồi chuyển cho kỹ thuật.", "updated_at": "2026-11-10T00:41:56.144255+00:00", "updated_by": "42ff9394-9c68-4ce2-9f2f-959abef2ebbf"}, {"key": "QT1.*.kiem_tra", "ord": 21, "prev": {"todo": "Soát phiếu, bảng và ghi chú\\nĐạt → gửi duyệt; sai → Trả về kèm lý do", "links": "", "notes": "", "purpose": "Kiểm tra nội dung phiếu và ghi chú của đơn. Đạt → gửi duyệt; sai → trả về người lập kèm lý do.", "updated_at": "2026-11-10T00:22:38.682729+00:00", "updated_by": null}, "todo": "Đối chiếu số lượng với danh sách tấm QT0\\nKiểm tra thành tiền, VAT, tổng thanh toán\\nĐạt → gửi duyệt; sai → Trả về kèm lý do", "links": "", "notes": "Trả về chỉ quay lại bước Lập của chính {cty}, không trả sang công ty khác.", "title": "QT1 · Kiểm tra", "purpose": "Kiểm tra XNĐH của {cty} trước khi trình duyệt.", "updated_at": "2026-11-10T01:08:28.719088+00:00", "updated_by": null}, {"key": "QT0.*.duyet", "ord": 14, "prev": {"todo": "Xem danh sách tấm và các lưu ý\\nĐối chiếu với yêu cầu của khách hàng\\nDuyệt, hoặc Trả về / Thất bại kèm lý do", "links": "", "notes": "Thất bại khi hao hụt lớn, vượt dự toán, không sản xuất được.", "purpose": "Người duyệt xác nhận bóc tách → QT0 hoàn tất. Hệ thống báo Zalo cho người lập XNĐH của Phương Nam: vào QT1 bấm \\"Mở XNĐH mới\\" và chọn lấy danh sách tấm QT0 (có thể gom nhiều lần bóc tách trước khi báo giá).", "updated_at": "2026-11-15T15:37:59.858465+00:00", "updated_by": "42ff9394-9c68-4ce2-9f2f-959abef2ebbf"}, "todo": "Xem danh sách tấm và các lưu ý\\nKiểm tra mức hao hụt nằm trong mức cho phép\\nĐối chiếu với yêu cầu của khách hàng\\nDuyệt, hoặc Trả về / Thất bại kèm lý do", "links": "", "notes": "Thất bại khi hao hụt lớn, vượt dự toán, không sản xuất được.", "title": "QT0 · Duyệt", "purpose": "Người duyệt xác nhận bóc tách → QT0 hoàn tất. Hệ thống báo Zalo cho người lập XNĐH của Phương Nam: vào QT1 bấm \\"Mở XNĐH mới\\" và chọn lấy danh sách tấm QT0 (có thể gom nhiều lần bóc tách trước khi báo giá).", "updated_at": "2026-11-15T15:38:36.450911+00:00", "updated_by": "42ff9394-9c68-4ce2-9f2f-959abef2ebbf"}, {"key": "QT1.*.lap", "ord": 20, "prev": {"todo": "Điền các trường bắt buộc và bảng\\nTích đủ checklist bắt buộc\\nGửi kiểm tra", "links": "", "notes": "", "purpose": "{cty} lập phiếu {phieu}. Công ty sau (IPC, Hanwa): dữ liệu đã được chép sẵn từ công ty trước, chỉ cần chỉnh giá / số lượng của mình.", "updated_at": "2026-11-10T00:22:38.682729+00:00", "updated_by": null}, "todo": "Nhập Số XNĐH, ngày lập, điều kiện giao hàng, thanh toán, VAT\\nNhập đơn giá cho từng dòng (thành tiền tự tính = tổng m² × đơn giá)\\nTích đủ checklist bắt buộc\\nGửi kiểm tra", "links": "", "notes": "Còn dòng chưa có đơn giá hoặc bảng danh sách tấm trống thì không chuyển bước được. Mỗi công ty chỉ thấy giá của mình.", "title": "QT1 · Lập phiếu", "purpose": "{cty} lập Xác nhận đơn hàng. PN lấy danh sách tấm từ QT0 (tắt được khi phải tách đơn); IPC và Hanwa nhận phiếu chép sẵn từ công ty trước, chỉ thay số XNĐH và đơn giá của mình.", "updated_at": "2026-11-10T01:08:28.719088+00:00", "updated_by": null}, {"key": "QT1.*.duyet", "ord": 22, "prev": {"todo": "Xem phiếu và ghi chú\\nDuyệt hoặc Trả về kèm lý do", "links": "", "notes": "", "purpose": "Người duyệt đọc thông tin phiếu và ghi chú rồi duyệt hoặc trả về. Duyệt xong phiếu được khoá.", "updated_at": "2026-11-10T00:22:38.682729+00:00", "updated_by": null}, "todo": "Xem giá, điều kiện thanh toán, tiến độ giao\\nDuyệt, hoặc Trả về kèm lý do", "links": "", "notes": "Có thể có thêm cấp duyệt (Quản trị → Luồng duyệt).", "title": "QT1 · Duyệt", "purpose": "Duyệt XNĐH của {cty}. Duyệt xong phiếu được khoá; PN → tự tạo phiếu cho IPC, IPC → cho Hanwa, Hanwa → chờ khách ký.", "updated_at": "2026-11-10T01:08:28.719088+00:00", "updated_by": null}, {"key": "QT2.*.lap", "ord": 30, "prev": {"todo": "Điền các trường bắt buộc và bảng\\nTích đủ checklist bắt buộc\\nGửi kiểm tra", "links": "", "notes": "", "purpose": "{cty} lập phiếu {phieu}. Công ty sau (IPC, Hanwa): dữ liệu đã được chép sẵn từ công ty trước, chỉ cần chỉnh giá / số lượng của mình.", "updated_at": "2026-11-10T00:22:38.682729+00:00", "updated_by": null}, "todo": "Tích checklist 5 điều kiện (bóc tách đã duyệt, đủ vật liệu, đủ công cụ, vấn đề kỹ thuật đã xử lý, đã công bố tiêu chuẩn QC)\\nNhập số lệnh, số hợp đồng, kho xuất / kho nhận, xưởng gia công\\nDán Bảng 1 – nguyên liệu và Bảng 2 – thành phẩm từ Excel\\nGửi kiểm tra", "links": "", "notes": "Thiếu số lệnh hoặc thiếu 1 trong 2 bảng thì không chuyển bước được. Hao hụt tự tính, định mức ~15%.", "title": "QT2 · Lập phiếu", "purpose": "{cty} lập Lệnh gia công từ Excel của phần mềm sản xuất. IPC và Hanwa nhận lệnh chép sẵn, chỉ nhập số lệnh và số hợp đồng của mình.", "updated_at": "2026-11-10T01:08:28.719088+00:00", "updated_by": null}, {"key": "QT2.*.kiem_tra", "ord": 31, "prev": {"todo": "Soát phiếu, bảng và ghi chú\\nĐạt → gửi duyệt; sai → Trả về kèm lý do", "links": "", "notes": "", "purpose": "Kiểm tra nội dung phiếu và ghi chú của đơn. Đạt → gửi duyệt; sai → trả về người lập kèm lý do.", "updated_at": "2026-11-10T00:22:38.682729+00:00", "updated_by": null}, "todo": "Đối chiếu quy cách, mác thép với đơn hàng\\nKiểm tra kho xuất / kho nhận\\nĐạt → gửi duyệt; sai → Trả về kèm lý do", "links": "", "notes": "", "title": "QT2 · Kiểm tra", "purpose": "Kiểm tra lệnh gia công của {cty}.", "updated_at": "2026-11-10T01:08:28.719088+00:00", "updated_by": null}, {"key": "QT2.*.duyet", "ord": 32, "prev": {"todo": "Xem phiếu và ghi chú\\nDuyệt hoặc Trả về kèm lý do", "links": "", "notes": "", "purpose": "Người duyệt đọc thông tin phiếu và ghi chú rồi duyệt hoặc trả về. Duyệt xong phiếu được khoá.", "updated_at": "2026-11-10T00:22:38.682729+00:00", "updated_by": null}, "todo": "Xem kế hoạch sản xuất, hao hụt\\nDuyệt, hoặc Trả về kèm lý do", "links": "", "notes": "", "title": "QT2 · Duyệt", "purpose": "Duyệt lệnh gia công của {cty}. Hanwa duyệt xong → in lệnh để ký tay bàn giao / nhận vật liệu.", "updated_at": "2026-11-10T01:08:28.719088+00:00", "updated_by": null}, {"key": "QT3.*.lap", "ord": 40, "prev": {"todo": "Điền các trường bắt buộc và bảng\\nTích đủ checklist bắt buộc\\nGửi kiểm tra", "links": "", "notes": "", "purpose": "{cty} lập phiếu {phieu}. Công ty sau (IPC, Hanwa): dữ liệu đã được chép sẵn từ công ty trước, chỉ cần chỉnh giá / số lượng của mình.", "updated_at": "2026-11-10T00:22:38.682729+00:00", "updated_by": null}, "todo": "Nhập số phiếu, ngày giao, địa điểm, đơn vị vận chuyển, xe, tài xế\\nDán danh sách thành phẩm của đợt (mã pallet, mã tấm, số tấm, m², kg)\\nTích đủ checklist bắt buộc\\nGửi kiểm tra", "links": "", "notes": "Bảng thành phẩm trống thì không chuyển bước được. Mỗi đợt giao là một phiếu riêng; tổng các đợt do phần mềm sản xuất đối chiếu.", "title": "QT3 · Lập phiếu", "purpose": "{cty} lập Phiếu xuất kho kiêm biên bản giao hàng cho một đợt giao. IPC và Hanwa nhận phiếu chép sẵn, chỉ nhập số phiếu của mình.", "updated_at": "2026-11-10T01:08:28.719088+00:00", "updated_by": null}, {"key": "QT3.*.kiem_tra", "ord": 41, "prev": {"todo": "Soát phiếu, bảng và ghi chú\\nĐạt → gửi duyệt; sai → Trả về kèm lý do", "links": "", "notes": "", "purpose": "Kiểm tra nội dung phiếu và ghi chú của đơn. Đạt → gửi duyệt; sai → trả về người lập kèm lý do.", "updated_at": "2026-11-10T00:22:38.682729+00:00", "updated_by": null}, "todo": "Đối chiếu số lượng giao với lệnh / đơn hàng\\nKiểm tra chứng từ giao hàng\\nĐạt → gửi duyệt; sai → Trả về kèm lý do", "links": "", "notes": "", "title": "QT3 · Kiểm tra", "purpose": "Kiểm tra phiếu giao hàng của {cty}.", "updated_at": "2026-11-10T01:08:28.719088+00:00", "updated_by": null}, {"key": "QT3.*.duyet", "ord": 42, "prev": {"todo": "Xem phiếu và ghi chú\\nDuyệt hoặc Trả về kèm lý do", "links": "", "notes": "", "purpose": "Người duyệt đọc thông tin phiếu và ghi chú rồi duyệt hoặc trả về. Duyệt xong phiếu được khoá.", "updated_at": "2026-11-10T00:22:38.682729+00:00", "updated_by": null}, "todo": "Xác nhận đồng ý xuất hàng\\nDuyệt, hoặc Trả về kèm lý do", "links": "", "notes": "", "title": "QT3 · Duyệt", "purpose": "Duyệt xuất hàng cho đợt giao của {cty}. Hanwa duyệt xong → in phiếu để khách ký nhận.", "updated_at": "2026-11-10T01:08:28.719088+00:00", "updated_by": null}, {"key": "sim.relap", "ord": 91, "prev": null, "todo": "Sửa theo lý do trả về (xem ở Hành trình duyệt)\\nGửi kiểm tra lại", "links": "", "notes": "Sai thông tin ở bước Lập: có thể xoá phiếu để lập lại (chỉ khi còn ở bước đầu).", "title": "Lập lại", "purpose": "Người lập sửa theo lý do rồi gửi kiểm tra lại. Thời gian chờ được tính tiếp vào hiệu quả của từng người.", "updated_at": "2026-11-10T00:22:38.682729+00:00", "updated_by": null}, {"key": "sim.final", "ord": 95, "prev": null, "todo": "In mẫu cho khách / người nhận ký tay\\nChụp hoặc scan bản đã ký\\nBấm \\"Tải bản đã ký\\" → hoàn tất", "links": "", "notes": "QT1: khách ký xác nhận. QT2: ký bàn giao / nhận vật liệu. QT3: khách ký nhận hàng.", "title": "Khách ký tay", "purpose": "Cả 3 công ty đã duyệt. Bên ký với khách (mặc định Hanwa) in mẫu và tải bản ký. Bấm \\"In mẫu cho khách ký\\" → in theo mẫu Excel, khách ký tay, chụp / scan rồi \\"Tải bản đã ký\\".", "updated_at": "2026-11-10T00:22:38.682729+00:00", "updated_by": null}]'::jsonb) on conflict do nothing;
