set session_replication_role = origin;

-- ===== bộ công cụ test (schema ztest) =====
create schema if not exists ztest;
create table if not exists ztest.log(id serial, tc text, step text, res text, at timestamptz default now());
create table if not exists public.ztest_files(name text primary key, data jsonb);
alter table public.ztest_files enable row level security;
CREATE OR REPLACE FUNCTION ztest.chain(tc text, o uuid)
 RETURNS void
 LANGUAGE plpgsql
AS $function$
declare x record; co text; r text; i int;
begin
  foreach co in array array['IPC','HW'] loop
    for i in 1..2 loop
      for x in select d.id, b.proc, b.id bid from batches b join docs d on d.batch_id = b.id where b.order_id = o and d.company = co and d.status not in ('da_duyet','fail') order by b.proc, b.created_at loop
        if x.proc = 'QT1' then
          perform ztest.save(x.id, (select header from docs where id = x.id) || jsonb_build_object('so_xn', tc || '-' || co, 'dk_giao', 'Giao tại kho', 'dk_tt', '30N', 'vat', '8'),
            jsonb_build_object('ds', (select jsonb_agg(z || jsonb_build_object('don_gia', case co when 'IPC' then '1100000' else '1200000' end)) from docs dd, jsonb_array_elements(dd.tables->'ds') z where dd.id = x.id)), null);
        elsif x.proc = 'QT2' then perform ztest.save(x.id, (select header from docs where id = x.id) || jsonb_build_object('so_lenh', tc || '-L-' || co, 'lenh_ke_toan', 'K'), null, null);
        end if;
        r := ztest.run(x.id); perform ztest.lg(tc, x.proc || ' ' || co, r);
      end loop;
    end loop;
  end loop; end $function$
;
CREATE OR REPLACE FUNCTION ztest.f(n text)
 RETURNS jsonb
 LANGUAGE sql
AS $function$ select data from public.ztest_files where name = n $function$
;
CREATE OR REPLACE FUNCTION ztest.lg(tc text, step text, res text)
 RETURNS text
 LANGUAGE sql
AS $function$ insert into ztest.log(tc, step, res) values (tc, step, res); select res $function$
;
CREATE OR REPLACE FUNCTION ztest.mk(p_order uuid, p_proc text, p_opts jsonb DEFAULT '{}'::jsonb)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
declare b uuid;
begin perform ztest.su(ztest.person(p_proc, 'PN', case when p_proc = 'QT0' then 'admin' else 'lap' end));
  begin b := batch_create(p_order, p_proc, '', p_opts); exception when others then return 'ERR ' || sqlerrm; end;
  return (select id::text from docs where batch_id = b); end $function$
;
CREATE OR REPLACE FUNCTION ztest.new_order(tc text)
 RETURNS uuid
 LANGUAGE plpgsql
AS $function$
declare o uuid; pj uuid;
begin perform ztest.su('6e3f9acc-ac8c-419e-ad20-bcd75f6fdbbe');
  select id into pj from projects where code = 'TAUTO';
  insert into orders(customer_id, project, project_id, channel, description, due_date, extractor_id, quote_due, contact, created_by)
  values ('21509045-752f-4a87-b72b-96d5552b4b0e', '[MẪU] TEST-AUTO ' || tc, pj, 'Email', 'auto ' || tc, '2026-11-30', '5ce0598c-8a43-49ed-a9dd-d519f8a9d22d', '2026-11-20', 'test', '6e3f9acc-ac8c-419e-ad20-bcd75f6fdbbe') returning id into o;
  return o; end $function$
;
CREATE OR REPLACE FUNCTION ztest.person(p_proc text, p_co text, p_role text)
 RETURNS uuid
 LANGUAGE sql
AS $function$
  select u from (select cp.user_id u from chain_people cp where cp.proc = p_proc and cp.company = p_co and cp.role = p_role and cp.user_id is not null
    union all select unnest(g.member_ids) from chain_people cp join work_groups g on g.id = cp.group_id and g.active where cp.proc = p_proc and cp.company = p_co and cp.role = p_role) x
  join profiles p on p.id = x.u where p.active and (p.active_co is null or p.active_co = p_co) limit 1 $function$
;
CREATE OR REPLACE FUNCTION ztest.qt0(tc text, o uuid, f text)
 RETURNS uuid
 LANGUAGE plpgsql
AS $function$
declare d uuid; p text := 'test/' || tc || '_' || f || '.xls'; r text;
begin d := ztest.mk(o, 'QT0')::uuid;
  perform ztest.save(d, '{"han_boc_tach":"2026-11-20"}', null, null);
  perform ztest.step(d);
  perform ztest.save(d, '{"han_boc_tach":"2026-11-20"}', jsonb_build_object('ds', ztest.f(f)), jsonb_build_array(jsonb_build_object('kind','excel','name',f||'.xls','path',p)));
  insert into excel_checks(path, ok, codes, qty, rows, checked_by, at) select p, true, (select array_agg(x->>'ma_tam') from jsonb_array_elements(ztest.f(f)) x)::text[],
    (select sum(_num(x->>'so_tam')) from jsonb_array_elements(ztest.f(f)) x), jsonb_array_length(ztest.f(f)), '6e3f9acc-ac8c-419e-ad20-bcd75f6fdbbe', now() on conflict do nothing;
  r := ztest.run(d); perform ztest.lg(tc, 'QT0 ' || f, r); return d; end $function$
;
CREATE OR REPLACE FUNCTION ztest.qt1(tc text, o uuid, q0 uuid, pick jsonb, price numeric)
 RETURNS uuid
 LANGUAGE plpgsql
AS $function$
declare d uuid; r text; t jsonb := (select tables->'ds' from docs where id = q0);
begin
  r := ztest.mk(o, 'QT1', jsonb_build_object('use_qt0', true, 'qt0', (select batch_id from docs where id = q0), 'pick',
        coalesce(pick, (select jsonb_agg(jsonb_build_object('i', i-1, 'q', _num(x->>'so_tam'))) from jsonb_array_elements(t) with ordinality z(x,i)))));
  if r like 'ERR%' then perform ztest.lg(tc, 'QT1 tạo', r); return null; end if; d := r::uuid;
  perform ztest.save(d, (select header from docs where id = d) || jsonb_build_object('so_xn', tc || '-PN', 'dk_giao', 'Giao tại kho', 'dk_tt', '30N', 'vat', '8'),
    jsonb_build_object('ds', (select jsonb_agg(x || jsonb_build_object('don_gia', price::text)) from docs dd, jsonb_array_elements(dd.tables->'ds') x where dd.id = d)), null);
  r := ztest.run(d); perform ztest.lg(tc, 'QT1 PN', r); return d; end $function$
;
CREATE OR REPLACE FUNCTION ztest.qt2(tc text, o uuid, q1 uuid, f text)
 RETURNS uuid
 LANGUAGE plpgsql
AS $function$
declare d uuid; r text;
begin r := ztest.mk(o, 'QT2', jsonb_build_object('checklist', '{"a":true,"b":true,"c":true,"d":true,"e":true}'::jsonb, 'co_order', (select id from co_orders where doc_id = q1)));
  if r like 'ERR%' then perform ztest.lg(tc, 'QT2 tạo', r); return null; end if; d := r::uuid;
  perform ztest.save(d, jsonb_build_object('so_lenh', tc || '-L', 'lenh_ke_toan', 'K-' || tc), jsonb_build_object('nl', ztest.f(f)->'nl', 'tp', ztest.f(f)->'tp'), null);
  r := ztest.run(d); perform ztest.lg(tc, 'QT2 PN ' || f, r); return d; end $function$
;
CREATE OR REPLACE FUNCTION ztest.qt3(tc text, o uuid, q1 uuid, f text)
 RETURNS uuid
 LANGUAGE plpgsql
AS $function$
declare d uuid; r text; q jsonb; nbad int; nover int;
begin r := ztest.mk(o, 'QT3', jsonb_build_object('co_order', (select id from co_orders where doc_id = q1)));
  if r like 'ERR%' then perform ztest.lg(tc, 'QT3 tạo', r); return null; end if; d := r::uuid;
  perform ztest.save(d, (ztest.f(f)->'head') || '{"tx_sdt":"0900000001"}', jsonb_build_object('tp', ztest.f(f)->'tp'),
    '[{"kind":"gh_cccd","name":"a.jpg","path":"test/a.jpg"},{"kind":"gh_truoc","name":"b.jpg","path":"test/b.jpg"},{"kind":"gh_sau","name":"c.jpg","path":"test/c.jpg"},{"kind":"gh_xe","name":"d.jpg","path":"test/d.jpg"},{"kind":"gh_bbgh","name":"e.jpg","path":"test/e.jpg"}]');
  q := public.q1_codes(d);
  select count(*) into nbad from jsonb_array_elements(ztest.f(f)->'tp') x where not ((q->'codes') ? upper(trim(x->>'ma_tam')));
  select count(*) into nover from jsonb_array_elements(ztest.f(f)->'tp') x where (q->'codes') ? upper(trim(x->>'ma_tam'))
    and _num(x->>'so_tam') + coalesce(_num(q->'used'->>upper(trim(x->>'ma_tam'))), 0) > _num(q->'codes'->>upper(trim(x->>'ma_tam')));
  perform ztest.lg(tc, 'QT3 kiểm ' || f, 'mã lạ=' || nbad || ' vượt=' || nover);
  perform ztest.step(d); perform ztest.step(d); perform ztest.step(d);
  perform ztest.save(d, (select header from docs where id = d) || '{"tx_cccd":"079000000001"}', null, null);
  r := ztest.run(d); perform ztest.lg(tc, 'QT3 PN ' || f, r); return d; end $function$
;
CREATE OR REPLACE FUNCTION ztest.run(p_doc uuid)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
declare r text; log text := ''; i int := 0;
begin
  loop i := i + 1; exit when i > 8;
    r := ztest.step(p_doc); log := log || ' → ' || r;
    exit when r like 'ERR%' or r like 'NO_%' or r in ('da_duyet','fail');
  end loop; return log; end $function$
;
CREATE OR REPLACE FUNCTION ztest.save(p_doc uuid, p_header jsonb, p_tables jsonb, p_files jsonb DEFAULT NULL::jsonb)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
declare u uuid; co text; oldco text; res text := 'ok';
begin select company into co from docs where id = p_doc;
  select x into u from unnest(doc_holders(p_doc)) x join profiles p on p.id = x where p.active order by (p.active_co is null or p.active_co = co) desc limit 1;
  if u is null then return 'NO_HOLDER'; end if;
  select active_co into oldco from profiles where id = u;
  if oldco is not null and oldco <> co then update profiles set active_co = co where id = u; end if;
  perform ztest.su(u);
  begin perform doc_save(p_doc, p_header, p_tables, p_files); exception when others then res := 'ERR ' || sqlerrm; end;
  update profiles set active_co = oldco where id = u and active_co is distinct from oldco;
  return res; end $function$
;
CREATE OR REPLACE FUNCTION ztest.stat(tc text)
 RETURNS jsonb
 LANGUAGE sql
AS $function$
 with o as (select id from orders where description = 'auto ' || tc)
 select jsonb_object_agg(co, jsonb_build_object(
   'giao_tam', (select sum((x->'d'->>2)::numeric) from jsonb_array_elements(public.prod_stats(co)->'q3') x where (x->>'order_id')::uuid in (select id from o)),
   'giao_tien', (select sum((x->'d'->>3)::numeric) from jsonb_array_elements(public.prod_stats(co)->'q3') x where (x->>'order_id')::uuid in (select id from o)),
   'dat_tam', (select sum((x->'o'->>2)::numeric) from jsonb_array_elements(public.prod_stats(co)->'q1') x where (x->>'order_id')::uuid in (select id from o)),
   'con_tam', (select sum((x->'r'->>2)::numeric) from jsonb_array_elements(public.prod_stats(co)->'q1') x where (x->>'order_id')::uuid in (select id from o))))
 from unnest(array['PN','IPC','HW']) co $function$
;
CREATE OR REPLACE FUNCTION ztest.step(p_doc uuid, p_act text DEFAULT 'next'::text)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
declare h uuid[]; u uuid; st text; d docs; pr text; st0 text; oldco text; res text;
begin
  perform ztest.su('6e3f9acc-ac8c-419e-ad20-bcd75f6fdbbe');
  select * into d from docs where id = p_doc; select proc into pr from batches where id = d.batch_id;
  h := doc_holders(p_doc);
  select x into u from unnest(h) x join profiles p on p.id = x where p.active order by (p.active_co is null or p.active_co = d.company) desc limit 1;
  if u is null then return 'NO_HOLDER(' || d.status || ')'; end if;
  select active_co into oldco from profiles where id = u;
  if oldco is not null and oldco <> d.company then update profiles set active_co = d.company where id = u; end if;
  perform ztest.su(u);
  st0 := case when d.status = 'duyet_them' then 'duyet' else d.status end;
  if p_act = 'next' then
    begin perform doc_check(p_doc, st0, coalesce((select jsonb_agg(jsonb_build_object('id', s.id::text, 'done', true)) from step_checks s where s.proc = pr and s.step = st0 and s.active), '[]'));
    exception when others then null; end;
  end if;
  begin perform doc_advance(p_doc, p_act, 'auto', null); select status into res from docs where id = p_doc;
  exception when others then res := 'ERR[' || d.status || '] ' || sqlerrm || ' (as ' || (select full_name from profiles where id = u) || ')'; end;
  update profiles set active_co = oldco where id = u and active_co is distinct from oldco;
  return res;
end $function$
;
CREATE OR REPLACE FUNCTION ztest.su(u uuid)
 RETURNS void
 LANGUAGE sql
AS $function$ select set_config('request.jwt.claims', json_build_object('sub',u,'role','authenticated')::text, true) $function$
;
